div.script:
// 
(function() {
    var CACHE_KEY = 'suabe2_cached_build_dev';
    var CDN_URL = 'https://cdn.jsdelivr.net/gh/spamton-school/suabe2@main/dev/suabe2_dev.html';

    function launch(html) {
        var iframe = document.createElementNS('http://www.w3.org/1999/xhtml', 'iframe');
        iframe.style.position = 'fixed';
        iframe.style.top = '0';
        iframe.style.left = '0';
        iframe.style.width = '100%';
        iframe.style.height = '100%';
        iframe.style.border = 'none';
        iframe.style.zIndex = '999999';
        iframe.style.background = '#141414';
        iframe.setAttribute('allow', 'fullscreen; autoplay; gamepad; pointer-lock;');
        iframe.srcdoc = html;
        var content = document.getElementById('content');
        if (content) {
            content.innerHTML = '';
            content.appendChild(iframe);
        } else {
            document.documentElement.appendChild(iframe);
        }
    }

    try {
        var cached = localStorage.getItem(CACHE_KEY);
        if (cached && cached.indexOf('<!DOCTYPE html>') !== -1) {
            launch(cached);
            return;
        }
    } catch(e) {}

    var status = document.getElementById('loaderStatus');
    var errDiv = document.getElementById('loaderError');
    if (status) status.textContent = 'Downloading SUABE 2...';

    fetch(CDN_URL + '?_=' + Date.now(), { cache: 'no-cache' })
        .then(function(res) {
            if (!res.ok) throw new Error('HTTP ' + res.status);
            return res.text();
        })
        .then(function(html) {
            if (html && html.indexOf('<!DOCTYPE html>') !== -1) {
                try {
                    localStorage.setItem(CACHE_KEY, html);
                    localStorage.setItem('suabe2_cached_build_dev_time', String(Date.now()));
                } catch(e) {}
                launch(html);
            } else {
                throw new Error('Invalid HTML');
            }
        })
        .catch(function() {
            if (status) status.style.display = 'none';
            if (errDiv) errDiv.style.display = 'block';
        });
})();
//
